export class Binary {
  constructor(binary) {
    this.binary = binary;
  }

  toDecimal() {
    if (typeof this.binary !== 'string' || !/^[01]+$/.test(this.binary)) {
      return null;
    }

    return this.binary
      .split('')
      .reduce((sum, digit) => sum * 2 + Number(digit), 0);
  }
}

